import json, sys

RUNS = "/c/micro/.state/runs"

FUNC_PASS = ["rollout_complete", "deployment_ready", "pods_ready",
             "endpoints_present", "http_health_ok"]
POSTURE = ["runs_as_nonroot", "readonly_rootfs", "no_priv_escalation", "caps_dropped"]

UNIV_AC = sorted([
    "securityContext.runAsNonRoot removed or weakened",
    "securityContext.allowPrivilegeEscalation removed or weakened",
    "securityContext.readOnlyRootFilesystem removed or weakened",
])

WO_EXPECT = {
    "rollout_complete": 10, "deployment_ready": 10, "pods_ready": 5,
    "endpoints_present": 10, "http_health_ok": 10,
    "runs_as_nonroot": 15, "readonly_rootfs": 10,
    "no_priv_escalation": 10, "caps_dropped": 10,
}


def load(d):
    def j(n):
        return json.load(open("%s/%s/%s" % (RUNS, d, n), encoding="utf-8"))
    return j("verdict.json"), j("checks.json"), j("meta.json")


def check_map(checks):
    return {c["id"]: (c["result"], c["weight"]) for c in checks["checks"]}


def report_volatile(tag, meta, verdict):
    print("  [%s] volatile: run_id=%s ns=%s image=%s started=%s" % (
        tag, verdict["run_id"], meta.get("namespace"),
        meta.get("image"), meta.get("started_at")))


def assert_broken(tag, d):
    v, c, m = load(d)
    cm = check_map(c)
    errs = []
    if v["score"] != 55:
        errs.append("verdict.score %r != 55" % v["score"])
    if c["score"] != 55:
        errs.append("checks.score %r != 55" % c["score"])
    if not v["matches_expectation"]:
        errs.append("matches_expectation is False")
    if v["expectation_problems"]:
        errs.append("expectation_problems=%r" % v["expectation_problems"])
    for cid in ["helm_release_ok"] + FUNC_PASS:
        if cm.get(cid, ("MISSING", 0))[0] != "PASS":
            errs.append("%s not PASS (%r)" % (cid, cm.get(cid)))
    for cid in POSTURE:
        if cm.get(cid, ("MISSING", 0))[0] != "FAIL":
            errs.append("%s not FAIL (%r)" % (cid, cm.get(cid)))
    if sorted(v["anticheat_violations"]) != UNIV_AC:
        errs.append("anticheat_violations=%r != universal-3" % v["anticheat_violations"])
    if m.get("scenario_checks") != POSTURE:
        errs.append("meta.scenario_checks=%r" % m.get("scenario_checks"))
    if m.get("weight_overrides") != WO_EXPECT:
        errs.append("meta.weight_overrides=%r" % m.get("weight_overrides"))
    report_volatile(tag, m, v)
    print("  [%s] score=%s" % (tag, v["score"]))
    print("  [%s] checks=%s" % (tag, {k: cm[k][0] for k in cm}))
    print("  [%s] anticheat=%s" % (tag, sorted(v["anticheat_violations"])))
    for e in errs:
        print("    CONTRACT-ERR [%s] %s" % (tag, e))
    return errs, (v, c, m, cm)


def assert_determinism(a, b):
    va, ca, ma, cma = a
    vb, cb, mb, cmb = b
    errs = []
    if va["score"] != vb["score"]:
        errs.append("score %s != %s" % (va["score"], vb["score"]))
    if cma != cmb:
        errs.append("per-check (result,weight) map differs:\n      %r\n      %r" % (cma, cmb))
    if ma.get("scenario_checks") != mb.get("scenario_checks"):
        errs.append("scenario_checks differ")
    if ma.get("weight_overrides") != mb.get("weight_overrides"):
        errs.append("weight_overrides differ")
    if va["matches_expectation"] != vb["matches_expectation"]:
        errs.append("matches_expectation differ")
    if va["expectation_problems"] != vb["expectation_problems"]:
        errs.append("expectation_problems differ")
    if sorted(va["anticheat_violations"]) != sorted(vb["anticheat_violations"]):
        errs.append("anticheat_violations differ")
    if va["evidence"] != vb["evidence"]:
        errs.append("evidence differ (%r/%r)" % (va["evidence"], vb["evidence"]))
