                    "endpoints_present", "http_health_ok", "config_applied"]
WO_EXPECT = {"rollout_complete": 15, "deployment_ready": 15,
             "pods_ready": 10, "config_applied": 15}


def load(d):
    def j(n):
        return json.load(open("%s/%s/%s" % (RUNS, d, n), encoding="utf-8"))
    return j("verdict.json"), j("checks.json"), j("meta.json")


def cmap(c):
    # exclude no_bad_events: weight-0, report-only, event-timing volatile on a
    # pod stuck in CreateContainerConfigError.
    return {x["id"]: (x["result"], x["weight"]) for x in c["checks"] if x["id"] != "no_bad_events"}


def rvol(tag, m, v):
    print("  [%s] volatile: run_id=%s ns=%s image=%s started=%s" % (
        tag, v["run_id"], m.get("namespace"), m.get("image"), m.get("started_at")))


def assert_broken(tag, d):
    v, c, m = load(d)
    cm = cmap(c)
    errs = []
    if v["score"] != 10:
        errs.append("verdict.score %r != 10" % v["score"])
    if c["score"] != 10:
        errs.append("checks.score %r != 10" % c["score"])
    if not v["matches_expectation"]:
        errs.append("matches_expectation is False")
    if v["expectation_problems"]:
        errs.append("expectation_problems=%r" % v["expectation_problems"])
    if cm.get("helm_release_ok", ("?", 0))[0] != "PASS":
        errs.append("helm_release_ok not PASS (%r)" % cm.get("helm_release_ok"))
    for cid in GRADED_FUNC_FAIL:
        if cm.get(cid, ("?", 0))[0] != "FAIL":
            errs.append("%s not FAIL (%r)" % (cid, cm.get(cid)))
    if v["anticheat_violations"]:
        errs.append("anticheat_violations=%r not empty" % v["anticheat_violations"])
    if m.get("scenario_checks") != ["config_applied"]:
        errs.append("meta.scenario_checks=%r" % m.get("scenario_checks"))
    if m.get("weight_overrides") != WO_EXPECT:
        errs.append("meta.weight_overrides=%r" % m.get("weight_overrides"))
    ev = v.get("evidence") or {}
    miss = [k for k, okv in ev.items() if not okv]
    if miss:
        errs.append("evidence needles missing: %r" % miss)
    if not ev:
        errs.append("verdict.evidence is empty (expected broken evidence scan)")
    rvol(tag, m, v)
    print("  [%s] score=%s" % (tag, v["score"]))
    print("  [%s] evidence=%s" % (tag, ev))
    print("  [%s] checks(graded)=%s" % (tag, {k: cm[k][0] for k in cm}))
    for x in c["checks"]:
        if x["id"] == "no_bad_events":
            print("  [%s] no_bad_events (ungraded/volatile) = %s :: %s" % (tag, x["result"], x["reason"]))
    for e in errs:
        print("    CONTRACT-ERR [%s] %s" % (tag, e))
    return errs, (v, c, m, cm)


def assert_determinism(a, b):
    va, ca, ma, cma = a
    vb, cb, mb, cmb = b
    errs = []
    if va["score"] != vb["score"]:
        errs.append("score %s != %s" % (va["score"], vb["score"]))
    if cma != cmb:
        errs.append("graded per-check map differs:\n      %r\n      %r" % (cma, cmb))
    if ma.get("scenario_checks") != mb.get("scenario_checks"):
        errs.append("scenario_checks differ")
    if ma.get("weight_overrides") != mb.get("weight_overrides"):
        errs.append("weight_overrides differ")
    if va["matches_expectation"] != vb["matches_expectation"]:
        errs.append("matches_expectation differ")
    if va["expectation_problems"] != vb["expectation_problems"]:
        errs.append("expectation_problems differ")
    if sorted(va["anticheat_violations"]) != sorted(vb["anticheat_violations"]):
        errs.append("anticheat_violations differ")
    if (va.get("evidence") or {}) != (vb.get("evidence") or {}):
        errs.append("evidence differ (%r / %r)" % (va.get("evidence"), vb.get("evidence")))
    for k in ("build_ok", "image_on_node", "rollout_ok"):
        if ma.get(k) != mb.get(k):
            errs.append("meta.%s differ (%r/%r)" % (k, ma.get(k), mb.get(k)))
    print("  [determinism] score %s==%s graded-map-equal=%s evidence-equal=%s anticheat-equal=%s" % (
        va["score"], vb["score"], cma == cmb,
        (va.get("evidence") or {}) == (vb.get("evidence") or {}),
        sorted(va["anticheat_violations"]) == sorted(vb["anticheat_violations"])))
    for e in errs:
        print("    DETERMINISM-ERR %s" % e)
    return errs


def assert_golden(d):
    v, c, m = load(d)
    cm = {x["id"]: (x["result"], x["weight"]) for x in c["checks"]}
    errs = []
    if v["score"] != 100:
        errs.append("verdict.score %r != 100" % v["score"])
    if c["score"] != 100:
        errs.append("checks.score %r != 100" % c["score"])
    if not v["matches_expectation"]:
        errs.append("matches_expectation is False")
    if v["expectation_problems"]:
        errs.append("expectation_problems=%r" % v["expectation_problems"])
    for cid in ("helm_release_ok", "rollout_complete", "deployment_ready", "pods_ready",
                "endpoints_present", "http_health_ok", "config_applied"):
        if cm.get(cid, ("?", 0))[0] != "PASS":
            errs.append("%s not PASS (%r)" % (cid, cm.get(cid)))
    if v["anticheat_violations"]:
        errs.append("anticheat_violations=%r not empty" % v["anticheat_violations"])
    if v["expected"].get("anticheat_clean") is not True:
        errs.append("expected.anticheat_clean is not True")
    rvol("golden", m, v)
    print("  [golden] score=%s" % v["score"])
    print("  [golden] checks=%s" % {k: cm[k][0] for k in cm})
    print("  [golden] config_applied: %s" % next(
        (x["reason"] for x in c["checks"] if x["id"] == "config_applied"), "?"))
    for e in errs:
        print("    CONTRACT-ERR [golden] %s" % e)
    return errs


def main():
    mode = sys.argv[1]
    if mode == "broken":
        e1, a = assert_broken("broken#1", sys.argv[2])
        e2, b = assert_broken("broken#2", sys.argv[3])
        e3 = assert_determinism(a, b)
        total = e1 + e2 + e3
        print("BROKEN RESULT: %d error(s)" % len(total))
        sys.exit(1 if total else 0)
    if mode == "golden":
        e = assert_golden(sys.argv[2])
        print("GOLDEN RESULT: %d error(s)" % len(e))
        sys.exit(1 if e else 0)
    print("bad mode %r" % mode)
    sys.exit(2)


main()

